        throw new NullPointerException("File must not be null");
    }

    if (file.isFile()) {
        file.deleteOnExit();
    } else if (file.isDirectory()) {
        file.deleteOnExit();
        String [] childFiles = file.list();
        for (String childFile : childFiles) {
