private byte[] toByteArray() {
    // Initialize a variable to store the total length of the byte array
    int totalLength = 0;

    // Loop through each byte buffer in the list
    for (ByteBuffer buffer : buffers) {
        // Get the current buffer's length
        int bufferLength = buffer.limit() - buffer.position();

        // Add the length to the total length
        totalLength += bufferLength;
    }

    // Create a new byte array with the total length
    byte[] result = new byte[totalLength];

    // Initialize an index variable to track the current position in the result array
    int index = 0;

    // Loop through each byte buffer in the list again
    for (ByteBuffer buffer : buffers) {
        // Get the current buffer's length
        int bufferLength = buffer.limit() - buffer.position();

        // Read the bytes from the buffer and write them to the result array
        buffer.get(result, index, bufferLength);

        // Increment the index by the buffer length
        index += bufferLength;
    }

    // Return the result array
    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    boolean hadSlash = false;
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            hadSlash = true;
        } else if (hadSlash) {
            // Escape character
            hadSlash = false;
            switch (ch) {
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case 'u':
                    i++;
                    if (i >= str.length()) {
                        sb.append('u');
                        break;
                    }
                    if (str.charAt(i) == '{') {
                        // Multi-char unicode escapes
                        while (i < str.length()) {
                            if (str.charAt(i) == '}') {
                                i++;
                                break;
                            }
                            sb.append(str.charAt(i));
                        }
                    } else {
                        // Single-char unicode escapes
                        int len = str.substring(i, i + 4).length();
                        if (len == 4) {
                            try {
                                sb.append((char) Integer.parseInt(str.substring(i, i + 4), 16));
                            } catch (NumberFormatException ex) {
                                sb.append('u');
                            }
                        } else {
                            sb.append('u');
                        }
                        i += 3;
                    }
                    break;
                default:
                    sb.append(ch);
                    continue;
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

