static int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    for (Symbol symbol : constantPool) {
        if (symbol.isNameAndType() && symbol.getName().equals(name) && symbol.getDescriptor().equals(descriptor)) {
            return symbol.getIndex();
        }
    }

    // Create a new CONSTANT_NameAndType_info and add it to the constant pool
    int index = constantPool.size() + 1;
    Symbol newSymbol = new Symbol(index, SymbolType.NAME_AND_TYPE);
