    NameAndType nameAndType = new NameAndType(name, descriptor);
    newSymbol.setValue(nameAndType);
    return index;
}

private static String unescapeId(String input) {
    if (input == null || input.isEmpty()) {
        return input;
    }
    StringBuilder output = new StringBuilder();
    int i = 0;
    while (i < input.length()) {
        char c = input.charAt(i);
        if (c != '\\') {
            output.append(c);
            i++;
            continue;
        }
        i++;
        if (i >= input.length()) {
            throw new IllegalArgumentException("Invalid escape sequence at the end of the string");
        }
        c = input.charAt(i++);
        switch (c) {
            case 'n':
                output.append('\n');
                break;
            case 'r':
                output.append('\r');
                break;
            case 't':
                output.append('\t');
                break;
            case '"':
                output.append('"');
                break;
            case '\\':
                output.append('\\');
                break;
            default:
                throw new IllegalArgumentException("Invalid escape sequence: \\" + c);
