List<SequenceRange> function() {
  // check if profiles are sorted
  if (!isSorted(profiles)) {
    throw new IllegalArgumentException("Profiles must be sorted by time");
  }

  // check if earliest profile time is less than or equal to the query time range start
  if (profiles.get(0).getTime() > query.getStartTime()) {
    throw new IllegalArgumentException("Earliest profile time must be less than or equal to the query time range start");
  }

  // check if latest profile time is greater than or equal to the query time range end
  if (profiles.get(profiles.size() - 1).getTime() < query.getEndTime()) {
    throw new IllegalArgumentException("Latest profile time must be greater than or equal to the query time range end");
  }

  // init sequence ranges list
  List<SequenceRange> sequenceRanges = new ArrayList<>();

  // init previous profile time
  long previousTime = profiles.get(0).getTime();

  // loop through profiles
  for (Profile profile : profiles) {
    long time = profile.getTime();

    // check if time is less than or equal to the query time range end
    if (time <= query.getEndTime()) {
      // check if time is greater than the previous time
      if (time > previousTime) {
        // add sequence range
        sequenceRanges.add(new SequenceRange(previousTime, time));
      }

      // update previous time
      previousTime = time;
    }
  }

  // check if latest profile time is within the query time range
  if (previousTime <= query.getEndTime()) {
    // add sequence range
    sequenceRanges.add(new SequenceRange(previousTime, query.getEndTime()));
  }

  // return sequence ranges
  return sequenceRanges;
}

