private List<Integer> computeUpperBounds(List<K> keys) {
    // Initialize the upper bound to the maximum integer value
    int upperBound = Integer.MAX_VALUE;

    // Iterate through the keys and calculate the minimum lower bound for each key
    for (K key : keys) {
        // Calculate the lower bound for the current key
        int lowerBound = key.hashCode() % upperBound;

        // Update the upper bound to be the minimum of the current lower bound and the previous upper bound
        upperBound = Math.min(upperBound, lowerBound);
    }

    // Return the computed key upper bound
    return Collections.singletonList(upperBound);
}

