public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
List<ThreadSnapshot> result = new ArrayList<>();

try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
    String line;
    int lineNumber = 0;
    while ((line = reader.readLine()) != null) {
        lineNumber++;
        Matcher matcher = sniffer.matcher(line);
        if (matcher.find()) {
            String tid = matcher.group(1);
            String sid = matcher.group(2);
            long ts = Long.parseLong(matcher.group(3));
            long eid = Long.parseInt(matcher.group(4));
            int status = Integer.parseInt(matcher.group(5));
            long ete = Long.parseLong(matcher.group(6));
            long ppid = Long.parseInt(matcher.group(7));

            if (timeRanges == null || timeRanges.isEmpty()) {
                result.add(new ThreadSnapshot(Long.parseLong(sid), Long.parseLong(tid), ts, eid, status, ete, ppid));
            } else {
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (timeRange.isInRange(ts)) {
                        result.add(new ThreadSnapshot(Long.parseLong(sid), Long.parseLong(tid), ts, eid, status, ete, ppid));
                    }
                }
            }
        }
    }
} catch (IOException e) {
    throw new IOException("Failed to parse file " + file + ", " + e.getMessage());
}
return result;
}
